#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i=0;i<10;i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    // For fast edge lookup
    vector<unordered_set<int>> adj_set(n+1);

    for(int i=0;i<m;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }
    for(int u=1;u<=n;u++){
        adj_set[u].reserve(adj[u].size()*2+2);
        for(int v: adj[u]) adj_set[u].insert(v);
    }

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){ return chrono::duration_cast<chrono::milliseconds>(now()-start_time).count(); };

    mt19937 rng(42);

    // Try topological sort for DAG - find longest path
    {
        vector<int> indeg(n+1,0);
        for(int u=1;u<=n;u++) for(int v:adj[u]) indeg[v]++;
        queue<int> q;
        for(int u=1;u<=n;u++) if(indeg[u]==0) q.push(u);
        vector<int> topo;
        topo.reserve(n);
        while(!q.empty()){
            int u=q.front();q.pop();
            topo.push_back(u);
            for(int v:adj[u]) if(--indeg[v]==0) q.push(v);
        }
        if((int)topo.size()==n){
            // DAG: find longest path via DP
            vector<int> dp(n+1,1), par(n+1,-1);
            // Process in reverse topo order
            // dp[u] = longest path starting at u
            // Actually process in reverse topo
            unordered_map<int,int> topo_pos;
            for(int i=0;i<n;i++) topo_pos[topo[i]]=i;
            // dp on topo order: dp[u] = 1 + max(dp[v]) for v in adj[u]
            vector<int> dp2(n+1,1), nxt(n+1,-1);
            for(int i=n-1;i>=0;i--){
                int u=topo[i];
                dp2[u]=1;
                nxt[u]=-1;
                for(int v:adj[u]){
                    if(dp2[v]+1>dp2[u]){
                        dp2[u]=dp2[v]+1;
                        nxt[u]=v;
                    }
                }
            }
            int best_start=topo[0];
            for(int u:topo) if(dp2[u]>dp2[best_start]) best_start=u;
            vector<int> path;
            for(int u=best_start;u!=-1;u=nxt[u]) path.push_back(u);
            if((int)path.size()==n){
                cout<<n<<"\n";
                for(int i=0;i<n;i++){cout<<path[i];if(i+1<n)cout<<' ';}
                cout<<"\n";
                return 0;
            }
            // If not full, still might be best - we'll compare later
            // For DAGs, this is optimal longest path
            cout<<path.size()<<"\n";
            for(int i=0;i<(int)path.size();i++){cout<<path[i];if(i+1<(int)path.size())cout<<' ';}
            cout<<"\n";
            return 0;
        }
    }

    vector<int> best_path;

    // Compute residual out-degree for Warnsdorff
    // We'll use a deque-based approach

    int max_iter = (n > 100000) ? 50 : (n > 10000 ? 200 : 2000);

    for(int iter=0; iter < max_iter && elapsed_ms() < 3200; iter++){
        int sv = rng() % n + 1;

        deque<int> path;
        vector<int> pos(n+1, -1);
        path.push_back(sv);
        pos[sv] = 0;

        // Greedy extend back with Warnsdorff
        auto extend_back = [&]() -> bool {
            int cur = path.back();
            int best = -1, best_sc = INT_MAX;
            for(int v : adj[cur]){
                if(pos[v] != -1) continue;
                int sc = 0;
                for(int w : adj[v]) if(pos[w]==-1) sc++;
                if(sc < best_sc || (sc == best_sc && (rng()&1))){
                    best_sc = sc; best = v;
                }
            }
            if(best == -1) return false;
            pos[best] = (int)path.size();
            path.push_back(best);
            return true;
        };

        auto extend_front = [&]() -> bool {
            int cur = path.front();
            int best = -1, best_sc = INT_MAX;
            for(int v : radj[cur]){
                if(pos[v] != -1) continue;
                int sc = 0;
                for(int w : radj[v]) if(pos[w]==-1) sc++;
                if(sc < best_sc || (sc == best_sc && (rng()&1))){
                    best_sc = sc; best = v;
                }
            }
            if(best == -1) return false;
            pos[best] = 0;
            path.push_front(best);
            // Update positions
            for(int i=0;i<(int)path.size();i++) pos[path[i]]=i;
            return true;
        };

        while(extend_back());
        while(extend_front());
        while(extend_back());

        // Directed Pósa rotations
        for(int rot=0; rot < min((int)path.size()*3, 5000) && (int)path.size()<n; rot++){
            int tail = path.back();
            // Find edges from tail to some path[i] where i < size-1
            vector<int> cands;
            for(int v : adj[tail]){
                if(pos[v]!=-1 && pos[v]+1 < (int)path.size()-1){
                    cands.push_back(pos[v]);
                }
            }
            if(cands.empty()) break;
            int pi = cands[rng() % cands.size()];
            // Truncate: keep path[0..pi, tail], discard path[pi+1..end-1]
            // Remove discarded vertices
            int new_end = pi + 2; // path[0..pi] + tail
            for(int j=(int)path.size()-1; j>pi; j--){
                if(path[j] != tail) pos[path[j]] = -1;
            }
            // Rebuild
            deque<int> newpath;
            for(int j=0;j<=pi;j++) newpath.push_back(path[j]);
            newpath.push_back(tail);
            path = newpath;
            for(int j=0;j<(int)path.size();j++) pos[path[j]]=j;

            // Try extending again
            while(extend_back());
            while(extend_front());
            while(extend_back());
        }

        if((int)path.size() > (int)best_path.size()){
            best_path.assign(path.begin(), path.end());
            if((int)best_path.size() == n) break;
        }
    }

    cout << best_path.size() << "\n";
    for(int i=0;i<(int)best_path.size();i++){
        cout << best_path[i];
        if(i+1<(int)best_path.size()) cout << ' ';
    }
    cout << "\n";
}
